from collections import Counter


def transform(grid):
    """Extract the right-hand panel and mark its non-background cells."""
    if not grid or not grid[0]:
        return []
    height, width = len(grid), len(grid[0])
    divider = next(
        (c for c in range(width)
         if all(grid[r][c] == grid[0][c] for r in range(height))
         and grid[0][c] != 0),
        None,
    )
    if divider is None:
        raise ValueError("missing solid vertical divider")
    left = [row[:divider] for row in grid]
    right = [row[divider + 1:] for row in grid]
    if any(len(a) != len(b) for a, b in zip(left, right)):
        raise ValueError("panels must have matching widths")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(lrow, rrow)]
            for lrow, rrow in zip(left, right)]

